<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}
require_once dirname(__DIR__).'/bootstrap.php';

$pdo=db();
$pdo->exec("UPDATE import_jobs SET status='QUEUED',error_message='Recovered after an interrupted worker' WHERE status='PROCESSING' AND updated_at<UTC_TIMESTAMP()-INTERVAL 30 MINUTE");
$pdo->beginTransaction();
try{$s=$pdo->query("SELECT * FROM import_jobs WHERE status='QUEUED' ORDER BY id LIMIT 1 FOR UPDATE SKIP LOCKED");$job=$s->fetch();if(!$job){$pdo->commit();fwrite(STDOUT,"No queued imports.\n");exit;}$pdo->prepare("UPDATE import_jobs SET status='PROCESSING' WHERE id=?")->execute([$job['id']]);$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}

$mapping=json_decode($job['column_mapping'],true,512,JSON_THROW_ON_ERROR);$batch=max(25,min(1000,(int)env('IMPORT_BATCH_SIZE','250')));$maxRows=(int)env('MAX_IMPORT_ROWS','100000');$failed=[];$imported=0;$duplicates=0;$processed=0;
$consume=function(array $raw,int $rowNumber)use(&$failed,&$imported,&$duplicates,&$processed,$mapping,$job,$pdo):void{
    $processed++;$values=[];$custom=[];
    foreach($mapping as $index=>$field){$value=trim((string)($raw[(int)$index]??''));if(str_starts_with($field,'custom:'))$custom[substr($field,7)]=mb_substr($value,0,1000);else$values[$field]=$value;}
    $email=strtolower($values['email']??'');$first=$values['first_name']??'';$last=$values['last_name']??'';$name=trim($values['full_name']??trim($first.' '.$last));
    if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)){$failed[]=[$rowNumber,$email,'Missing first/full name or invalid email'];return;}
    if($first==='')$first=trim((string)strtok($name,' '));
    $status=strtoupper(str_replace(' ','_',$values['status']??'NEW'));if(!in_array($status,['NEW','CONTACTED','QUALIFIED','SEND_FAILED','BOUNCED','UNSUBSCRIBED'],true))$status='NEW';
    $url=function(string $key)use($values):?string{return normalize_import_url($values[$key]??null);};
    $company=mb_substr($values['company_name']??'',0,120)?:null;
    $phone=mb_substr($values['phone']??'',0,40)?:null;try{$phoneNormalized=$phone?normalize_phone($phone):null;}catch(ApiError){$failed[]=[$rowNumber,$email,'Invalid personal phone'];return;}
    try{$pdo->prepare('INSERT INTO leads (tenant_id,public_id,name,first_name,last_name,email,email_normalized,phone,phone_normalized,company,company_name,website,job_title,linkedin,facebook,instagram,twitter,tiktok,other_socials,location,country,source,custom_fields,status,tags,notes,created_by,assigned_user_id) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$job['tenant_id'],uuid(),mb_substr($name,0,100),mb_substr($first,0,100)?:null,mb_substr($last,0,100)?:null,$email,$email,$phone,$phoneNormalized,$company,$company,$url('website'),mb_substr($values['job_title']??'',0,150)?:null,$url('linkedin'),$url('facebook'),$url('instagram'),$url('twitter'),$url('tiktok'),!empty($values['other_social_links'])?json_encode(array_filter(array_map('trim',explode(',',$values['other_social_links']))),JSON_THROW_ON_ERROR):null,mb_substr($values['location']??'',0,255)?:null,mb_substr($values['country']??'',0,100)?:null,mb_substr($values['source']??'',0,100)?:null,$custom?json_encode($custom,JSON_THROW_ON_ERROR):null,$status,json_encode(array_values(array_filter(array_map('trim',explode(',',$values['tags']??'')))),JSON_THROW_ON_ERROR),mb_substr($values['notes']??'',0,10000)?:null,$job['created_by'],$job['created_by']]);$imported++;}catch(PDOException $e){if($e->getCode()==='23000'){$duplicates++;return;}throw $e;}
};

try{
    $ext=strtolower(pathinfo($job['storage_path'],PATHINFO_EXTENSION));
    if($ext==='csv'){$h=fopen($job['storage_path'],'rb');if(!$h)throw new RuntimeException('Unable to open import file.');fgetcsv($h);$row=1;while(($raw=fgetcsv($h))!==false){$row++;if($processed>=$maxRows)throw new RuntimeException('Import row limit exceeded.');$consume($raw,$row);if($processed%$batch===0)$pdo->prepare('UPDATE import_jobs SET processed_rows=?,imported_rows=?,duplicate_rows=?,failed_rows=? WHERE id=?')->execute([$processed,$imported,$duplicates,count($failed),$job['id']]);}fclose($h);}
    else{$info=PhpOffice\PhpSpreadsheet\IOFactory::createReaderForFile($job['storage_path']);$info->setReadDataOnly(true);$sheetInfo=$info->listWorksheetInfo($job['storage_path']);$total=(int)($sheetInfo[0]['totalRows']??0);for($start=2;$start<=$total;$start+=$batch){$end=min($start+$batch-1,$total,$maxRows+1);$reader=PhpOffice\PhpSpreadsheet\IOFactory::createReaderForFile($job['storage_path']);$reader->setReadDataOnly(true);$reader->setReadFilter(new class($start,$end) implements PhpOffice\PhpSpreadsheet\Reader\IReadFilter{public function __construct(private int $start,private int $end){}public function readCell(string $columnAddress,int $row,string $worksheetName=''):bool{return $row>=$this->start&&$row<=$this->end;}});$rows=$reader->load($job['storage_path'])->getActiveSheet()->toArray(null,true,true,false);foreach(array_slice($rows,$start-1,$end-$start+1,true) as $index=>$raw)$consume($raw,(int)$index+1);unset($rows,$reader);$pdo->prepare('UPDATE import_jobs SET processed_rows=?,imported_rows=?,duplicate_rows=?,failed_rows=? WHERE id=?')->execute([$processed,$imported,$duplicates,count($failed),$job['id']]);if($end>=$maxRows+1&&$total>$maxRows+1)throw new RuntimeException('Import row limit exceeded.');}}
    $report=null;if($failed){$report=dirname($job['storage_path']).'/'.$job['public_id'].'-failed.csv';$h=fopen($report,'wb');fputcsv($h,['Row','Email','Reason']);foreach($failed as $failure)fputcsv($h,$failure);fclose($h);chmod($report,0600);}
    $pdo->prepare("UPDATE import_jobs SET status='COMPLETED',total_rows=?,processed_rows=?,imported_rows=?,duplicate_rows=?,failed_rows=?,failed_report_path=? WHERE id=?")->execute([$processed,$processed,$imported,$duplicates,count($failed),$report,$job['id']]);audit('import.completed','import_job',$job['public_id'],['imported'=>$imported,'duplicates'=>$duplicates,'failed'=>count($failed)],['tenant_id'=>$job['tenant_id'],'id'=>$job['created_by']]);fwrite(STDOUT,"Imported {$imported} lead(s).\n");
}catch(Throwable $e){error_log('[LeadPilot import] '.$e->getMessage());$pdo->prepare("UPDATE import_jobs SET status='FAILED',error_message=? WHERE id=?")->execute([mb_substr($e->getMessage(),0,500),$job['id']]);throw $e;}
